"use client";

import { useMemo } from "react";
import { motion, type Variants } from "motion/react";
import { cn } from "@/lib/utils";

interface SpecterProps {
	text?: string;
	ghostCount?: number;
	drift?: number;
	speed?: number;
	angle?: number;
	stagger?: number;
	blur?: number;
	splitColor1?: string;
	splitColor2?: string;
	reducedMotion?: boolean;
	className?: string;
}

const BASE_CYCLE = 1.6;

function resolveBlend(): "plus-lighter" | "screen" {
	if (
		typeof window !== "undefined" &&
		typeof CSS !== "undefined" &&
		typeof CSS.supports === "function" &&
		CSS.supports("mix-blend-mode", "plus-lighter")
	) {
		return "plus-lighter";
	}
	return "screen";
}

export default function Specter({
	text = "SPECTER",
	ghostCount = 3,
	drift = 24,
	speed = 1,
	angle = 90,
	stagger = 0.15,
	blur = 2,
	splitColor1 = "#a855f7",
	splitColor2 = "#22d3ee",
	reducedMotion = false,
	className = "",
}: SpecterProps) {
	const blend = useMemo(resolveBlend, []);

	const count = Math.max(0, Math.round(ghostCount));
	const cycle = Math.max(0.15, BASE_CYCLE / Math.max(0.05, speed));
	const rad = (angle * Math.PI) / 180;
	const dx = Math.cos(rad) * drift;
	const dy = Math.sin(rad) * drift;

	const variants: Variants = useMemo(
		() => ({
			still: {
				opacity: 0,
				x: 0,
				y: 0,
				filter: "blur(0px)",
				transition: { duration: 0.25, ease: "easeOut" },
			},
			run: (i: number) => ({
				opacity: [1, 0],
				x: [0, dx],
				y: [0, dy],
				filter: ["blur(0px)", `blur(${blur}px)`],
				transition: {
					duration: cycle,
					delay: i * stagger,
					repeat: Infinity,
					ease: "easeOut",
				},
			}),
		}),
		[dx, dy, blur, cycle, stagger],
	);

	return (
		<span
			aria-label={text}
			className={cn(
				"relative inline-block whitespace-pre text-ink",
				className,
			)}
		>
			<span aria-hidden className="relative z-0 block">
				{text}
			</span>

			{Array.from({ length: count }, (_, i) => (
				<motion.span
					key={i}
					aria-hidden
					custom={i}
					variants={variants}
					initial="still"
					animate={reducedMotion ? "still" : "run"}
					className="pointer-events-none absolute inset-0 flex items-center justify-center"
					style={{
						color: i % 2 === 0 ? splitColor1 : splitColor2,
						mixBlendMode: blend,
						willChange: "transform, opacity, filter",
					}}
				>
					{text}
				</motion.span>
			))}
		</span>
	);
}
